(()=>{
const config=()=>REGIONAL_WORKSPACES[sessionStorage.getItem('yunxu-role')];
const sessions=roleSessions;roleSessions=function(){const c=config(),role=sessionStorage.getItem('yunxu-role');if(c&&!sessionRecords.some(x=>x.role===role)){c.tasks.slice(0,2).forEach((t,i)=>sessionRecords.push({id:role+'-session-'+i,role,source:'manual',title:t.title,time:Date.now()-i*60000,messages:[{user:false,text:t.desc}]}));saveSessionRecords()}return sessions()};
const dashboard=applyWarehouseDashboard;applyWarehouseDashboard=function(){dashboard();const c=config();if(!c)return;document.getElementById('stats').innerHTML=[['待协同事项',c.tasks.filter(t=>t.state==='todo').length,'项'],['待复核事项',c.tasks.filter(t=>t.state==='doing').length,'项'],['覆盖业务',c.groups.length,'类'],['已完成',c.tasks.filter(t=>t.state==='done').length,'项']].map(x=>'<div class="stat"><div class="statlabel">'+x[0]+'</div><div class="number">'+x[1]+' <small>'+x[2]+'</small></div><div class="statfoot">'+c.name+' · 示例数据</div></div>').join('');document.querySelector('.ai-suggestions').innerHTML=c.groups.flatMap(g=>g.skills).slice(0,4).map(name=>'<button data-regional-prompt="'+name+'">'+name+'</button>').join('');document.querySelectorAll('[data-regional-prompt]').forEach(b=>b.onclick=()=>suggest('请协助'+b.dataset.regionalPrompt+'，整理相关业务依据和待确认事项。'));const img=document.querySelector('.composer-mascot');img.src=c.image;img.alt=c.name+'形象'};
const concerns=renderConcerns;renderConcerns=function(tab){const c=config();if(!c)return concerns(tab);document.getElementById('concerns').innerHTML='<div class="concern-head"><h2>你可能关注</h2><small>'+c.name+'协同事项</small></div><div class="concern-panel concern-table"><table><thead><tr><th>业务事项</th><th>具体内容</th><th>状态</th></tr></thead><tbody>'+c.tasks.map(t=>'<tr><td>'+t.title+'</td><td>'+t.desc+'</td><td>'+(t.state==='doing'?'待确认':'运行中')+'</td></tr>').join('')+'</tbody></table></div>'};
})();
